#pragma once

#include <functional>
#include <thread>

// java.util.concurrent.ThreadFactory 接口桩。
// 按需创建新线程，供线程池等组件自定义线程属性。
class ThreadFactory {
public:
    virtual ~ThreadFactory() = default;

    // 创建一个新线程执行 r（对应 Java 的 newThread(Runnable)）
    virtual std::thread newThread(std::function<void()> r) = 0;
};
